bool NativeMonotonicDepthModuleCertified(std::string_view source, bool pixel,
    NativeShaderVariant variant, std::span<const uint8_t> bytes) noexcept {
    if (source.size() != 64 || bytes.empty() || bytes.size() > 1024u * 1024u ||
        (variant != NativeShaderVariant::Unmodified &&
         (variant != NativeShaderVariant::PipelineStateEpilogueV1 || !pixel)))
        return false;
    for (const auto& pin : kPins) {
        if (pin.source != source || pin.pixel != pixel || pin.variant != variant)
            continue;
        if (pin.bytes != bytes.size()) return false;
        try { return ContentHash(bytes) == pin.spirv; }
        catch (...) { return false; } // Optional proof always fails closed.
    }
    return false;
}

